from __future__ import annotations

from typing import Any

from orders.application.errors import OrderNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import Response, conflict, not_found
from orders.infrastructure.catalog import InMemoryProductCatalog
from orders.infrastructure.customers import InMemoryCustomerRepository


class FulfilmentController:
    def __init__(self, service: OrderService, catalog: InMemoryProductCatalog,
                 customers: InMemoryCustomerRepository) -> None:
        self._service = service
        self._catalog = catalog
        self._customers = customers

    def handle_packing_slip(self, order_id: str) -> Response:
        try:
            order = self._service.get_order(order_id)
        except OrderNotFound:
            return not_found("order")

        if order.status == "cancelled":
            return conflict(Exception(f"order {order_id} is cancelled"))

        customer = self._customers.get(order.customer_id)
        customer_name = customer.name if customer else ""

        lines = []
        for item in order.items:
            product = self._catalog.get(item.sku)
            product_name = product.name if product else ""
            lines.append({
                "sku": item.sku,
                "name": product_name,
                "quantity": item.quantity,
            })

        return Response(200, {
            "order_id": order.order_id,
            "customer_name": customer_name,
            "lines": lines,
        })

